/**
 * Names for everything the audio kit can play, and the small tables that tie sound to the
 * world: which voice a biome speaks with, which bed a biome plays, which sound an event fires.
 *
 * Files live under /assets/audio (a symlink to the repo's assets/audio). SFX and voices are
 * generated by tools/sound-factory; music is third-party CC0 / CC-BY and every track here
 * carries the credit line its license asks for (full list: assets/audio/music/CREDITS.md).
 */

import type { BiomeId, CharacterState } from "@/lib/world/types";
import type { VoiceMood } from "./schedule.ts";

export type { VoiceMood };

export const AUDIO_BASE = "/assets/audio";

