export type SfxName = (typeof SFX_NAMES)[number];

export function sfxFile(name: SfxName): string {
  return `${AUDIO_BASE}/sfx/${name}.wav`;
}

// ---------- voices (tools/sound-factory/blips.mjs; assets/audio/voices/manifest.json) ----------

export const VOICE_SPECIES = ["peach", "coral", "mint", "olive", "lilac"] as const;
export type VoiceSpecies = (typeof VOICE_SPECIES)[number];

export const VOICE_LETTERS = "abcdefghijklmnopqrstuvwxyz";

export function voiceFile(species: VoiceSpecies, letter: string): string {
  return `${AUDIO_BASE}/voices/${species}/${letter}.wav`;
}

/**
 * One voice per creature accent, the way the factory paints them. Until a character carries
 * its own accent, the biome default in lib/world/layout.ts decides.
 */
export const ACCENT_VOICE: Record<string, VoiceSpecies> = {
  "#f2a86f": "peach",
  "#e88a8a": "coral",
  "#8fc9d8": "mint",
  "#b9c96f": "olive",
  "#c9a2e6": "lilac",
};

export const BIOME_VOICE: Record<BiomeId, VoiceSpecies> = {
  forest: "peach",
  city: "coral",
  ice: "mint",
  sand: "olive",
  meadow: "lilac",
};

export function voiceFor(biome: BiomeId, accentHex?: string): VoiceSpecies {
  return (accentHex && ACCENT_VOICE[accentHex.toLowerCase()]) || BIOME_VOICE[biome];
}

export const MOOD_FOR_STATE: Record<CharacterState, VoiceMood> = {
  idle: "neutral",
  evolved: "happy",
  recovered: "happy",
  exploded: "sad",
  faded: "sad",
};

// ---------- music (assets/audio/music/catalog.json, shortlisted) ----------

export interface BgmTrack {
  id: string;
  title: string;
  artist: string;
  license: string;
  /** the exact line the license asks us to show */
  credit: string;
  source: string;
  file: string;
  /** trim for beds that sit under speech and SFX; 1 = as mastered */
  gain: number;
}

const track = (t: Omit<BgmTrack, "gain"> & { gain?: number }): BgmTrack => ({ gain: 1, ...t });

